<script setup lang="ts">import {computed} from 'vue';import type {Ranking} from '../types/domain';const props=defineProps<{rows:Ranking[]}>();const maxX=computed(()=>Math.max(.001,...props.rows.map(r=>r.d_plus||0))*1.12);const maxY=computed(()=>Math.max(.001,...props.rows.map(r=>r.d_minus||0))*1.12);</script><template><svg class="distance-plot" viewBox="0 0 600 290" aria-label="TOPSIS理想点距离散点"><line x1="45" x2="575" y1="240" y2="240"/><line x1="45" x2="45" y1="20" y2="240"/><g v-for="v in [.25,.5,.75,1]" :key="v"><line class="grid" x1="45" x2="575" :y1="240-v*210" :y2="240-v*210"/><text x="3" :y="244-v*210">{{(maxY*v).toFixed(2)}}</text></g><g v-for="r in rows" :key="r.alternative_id"><circle v-if="r.d_plus!=null&&r.d_minus!=null" :cx="45+r.d_plus/maxX*515" :cy="240-r.d_minus/maxY*210" :r="r.rank===1?7:4" :class="{best:r.rank===1}"><title>{{r.name}} / 贴近度{{r.score?.toFixed(4)}}</title></circle><text v-if="r.rank===1&&r.d_plus!=null&&r.d_minus!=null" :x="56+r.d_plus/maxX*515" :y="234-r.d_minus/maxY*210">{{r.alternative_id}}</text></g><text x="207" y="278">到优理想点距离 →（越小越好）</text><text x="55" y="18">到劣理想点距离 ↑（越大越好）</text></svg></template>
